function minCost(nums) {
  const n = nums.length;
  let next = n % 2 === 0 ? n - 1 : n;
  let dp = [];
  for (let keep = 0; keep < next; keep++) {
    dp.push(next === n ? nums[keep] : Math.max(nums[keep], nums[n - 1]));
  }

  for (next -= 2; next >= 1; next -= 2) {
    const b = nums[next];
    const c = nums[next + 1];
    const row = [];
    for (let keep = 0; keep < next; keep++) {
      const a = nums[keep];
      const keepA = Math.max(b, c) + dp[keep];
      const keepB = Math.max(a, c) + dp[next];
      const keepC = Math.max(a, b) + dp[next + 1];
      row.push(Math.min(keepA, keepB, keepC));
    }
    dp = row;
  }
  return dp[0];
}

