function minCost(nums) {
  // Play out every possible sequence of operations on real arrays and keep the cheapest one.
  const clear = (values) => {
    if (values.length < 3) return Math.max(...values);
    let best = Infinity;
    for (const [x, y] of [[0, 1], [0, 2], [1, 2]]) {
      const rest = values.filter((_, index) => index !== x && index !== y);
      best = Math.min(best, Math.max(values[x], values[y]) + clear(rest));
    }
    return best;
  };
  return clear(nums);
}

