function generate(rand, size) {
  const large = size === 'large';
  // Large inputs use both parities of the length, since the last layer of states differs between them.
  const n = large ? 999 + Math.floor(rand() * 2) : 1 + Math.floor(rand() * 12);
  const top = large ? 1000000 : [1, 3, 10, 1000000][Math.floor(rand() * 4)];
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
